import numpy as np, itertools
def score2(atoms,bonds):
    X=np.array([a[1] for a in atoms]); el=[a[0] for a in atoms]; n=len(atoms)
    adj=[set() for _ in range(n)]
    for i,j in bonds: adj[i].add(j); adj[j].add(i)
    excl=np.zeros((n,n),bool)
    for i in range(n):
        for j in adj[i]:
            excl[i,j]=excl[j,i]=True
            for k in adj[j]: excl[i,k]=excl[k,i]=True
    D=np.linalg.norm(X[:,None]-X[None],axis=-1)
    np.fill_diagonal(excl,True)
    Dm=np.where(excl,99,D)
    k=np.unravel_index(np.argmin(Dm),Dm.shape)
    return Dm.min(),(k[0],el[k[0]],k[1],el[k[1]])
cands=[]
for tilt in [45,55,65]:
  for sep in [110,130,150]:
    t=np.radians(tilt); s2=np.radians(sep/2)
    for yf in [0.0,0.4]:
      cands.append(([-np.sin(t)*np.sin(s2), np.sin(t)*np.cos(s2)*yf, np.cos(t)],
                    [ np.sin(t)*np.sin(s2), np.sin(t)*np.cos(s2)*yf, np.cos(t)]))
best=None
for u1,u2 in cands:
 for z3 in [-1.2,-0.9,-0.6]:
